  "coque.accueil.etape_canaux": {"fr": "Où vous publiez", "en": "Where you post"},
  "coque.accueil.etape_fournisseurs": {"fr": "Fournisseurs de génération", "en": "Generation providers"},
  "coque.accueil.etape_persona": {"fr": "Choisir un persona", "en": "Pick a persona"},
  "coque.accueil.etape_pret": {"fr": "Vous êtes prêt", "en": "You’re ready"},
  "coque.accueil.fournisseurs_prets": {"fr": "Fournisseurs prêts", "en": "Providers ready"},
  "coque.accueil.generateurs": {"fr": "Générateurs", "en": "Generators"},
  "coque.accueil.generateurs_texte": {"fr": "Les badges reflètent le contenu de backend/.env. Seul fal.ai est requis. Pour les plans marketing, vous pouvez utiliser Anthropic (cloud) OU un modèle Ollama local : avec Ollama, rien ne quitte votre machine. Modifiez backend/.env et redémarrez pour appliquer.", "en": "The badges reflect what's in backend/.env. Only fal.ai is required. For marketing plans you can use Anthropic (cloud) OR a local Ollama model — nothing leaves your machine with Ollama. Edit backend/.env and restart to apply."},
  "coque.accueil.generateurs_titre": {"fr": "Branchez vos fournisseurs de génération.", "en": "Plug in your generation providers."},
  "coque.accueil.local_1": {"fr": "Tout tourne en local. Les clés d'API vont dans ", "en": "Everything runs locally. API keys go in "},
  "coque.accueil.local_2": {"fr": ". Vos rendus ne quittent pas votre machine avant qu'un post du Planificateur ne parte.", "en": ". Your renders never leave your machine until a Scheduler post fires."},
  "coque.accueil.ollama": {"fr": "Ollama (LLM local)", "en": "Ollama (local LLM)"},
  "coque.accueil.ouvrez": {"fr": " Ouvrez ", "en": " Open "},
  "coque.accueil.pas_encore": {"fr": "pas encore", "en": "not yet"},
  "coque.accueil.passer": {"fr": "Passer pour l'instant", "en": "Skip for now"},
  "coque.accueil.persona_actif": {"fr": "Persona actif", "en": "Active persona"},
  "coque.accueil.persona_texte": {"fr": "Chaque persona est un fichier JSON avec un ton, un vocabulaire et un mode de voix. Le persona actif règle le scénariste des News, le générateur de prompts et la voix off par défaut. Vous pouvez en changer à tout moment depuis les Réglages.", "en": "Each persona is a JSON file with tone, vocabulary and a voice mode. The active one shapes the News scripter, the prompt generator and the default voiceover. You can swap any time from Settings."},
  "coque.accueil.persona_titre": {"fr": "Choisissez ou créez une voix.", "en": "Pick or create a voice."},
  "coque.accueil.pret": {"fr": "Prêt", "en": "Ready"},
  "coque.accueil.pret_texte": {"fr": "Ouvrez le Studio pour composer votre premier graphe, ou filez au Planificateur pour organiser la semaine. Vous pouvez revoir cette liste depuis la palette de commandes (⌘K → « Revoir l'accueil »).", "en": "Open Studio to compose your first graph, or go straight to Scheduler to plan the week. You can revisit this checklist from the command palette (⌘K → 'Replay onboarding')."},
  "coque.accueil.pret_titre": {"fr": "Les profondeurs sont calibrées.", "en": "The deep is calibrated."},
  "coque.accueil.redemarrez": {"fr": " et redémarrez le backend. L'état se met à jour ici tout seul (vérifié toutes les 10 s).", "en": " and restart the backend. The status updates here automatically (polled every 10s)."},
