  "reglages.appareils.aide": {"fr": "Un téléphone appairé peut LIRE ce que ce PC produit, par le Wi-Fi de la maison. Il ne peut ni écrire, ni dépenser, ni voir vos clés : celles-ci voyagent seulement par l’archive chiffrée du Coffre.", "en": "A paired phone can READ what this PC produces, over your home Wi-Fi. It cannot write, spend, or see your keys: those travel only through the Vault's encrypted archive."},
  "reglages.appareils.appaire": {"fr": "« {nom} » appairé", "en": "“{nom}” paired"},
  "reglages.appareils.appaire_le": {"fr": "appairé le {date}", "en": "paired on {date}"},
  "reglages.appareils.appairer": {"fr": "Appairer un appareil", "en": "Pair a device"},
  "reglages.appareils.appairer_aide": {"fr": "Affiche un QR valable 5 minutes pour UN appareil", "en": "Shows a QR code valid for 5 minutes for ONE device"},
  "reglages.appareils.appareil": {"fr": "appareil", "en": "device"},
  "reglages.appareils.aucun": {"fr": "Aucun appareil appairé.", "en": "No paired device."},
  "reglages.appareils.chargement": {"fr": "Appareils…", "en": "Devices…"},
  "reglages.appareils.compte": {"fr": "{n} / {max} appareils", "en": "{n} / {max} devices"},
  "reglages.appareils.console": {"fr": "Ouvre la console {nom} ({cle})", "en": "Opens the {nom} console ({cle})"},
  "reglages.appareils.erreur": {"fr": "Appairage : {detail}", "en": "Pairing: {detail}"},
  "reglages.appareils.fermer_qr": {"fr": "Fermer le QR", "en": "Close QR code"},
  "reglages.appareils.fermer_qr_aide": {"fr": "Ferme le QR ; son secret expirera seul", "en": "Closes the QR code; its secret will expire on its own"},
  "reglages.appareils.garder": {"fr": "Garder", "en": "Keep"},
  "reglages.appareils.lan_ferme": {"fr": "L’application n’écoute que ce PC : un téléphone ne peut pas l’atteindre. Pour l’ouvrir au Wi-Fi, remplacez HOST=127.0.0.1 par HOST=0.0.0.0 dans le fichier .env du dossier de données, puis relancez l’application (Windows demandera d’autoriser Python dans le pare-feu). Sans jeton d’appareil, rien n’est lisible depuis le Wi-Fi.", "en": "The app only listens on this PC: a phone cannot reach it. To open it to Wi-Fi, replace HOST=127.0.0.1 with HOST=0.0.0.0 in the .env file of the data folder, then restart the app (Windows will ask to allow Python through the firewall). Without a device token, nothing can be read over Wi-Fi."},
  "reglages.appareils.lan_ouvert": {"fr": "réseau local ouvert", "en": "local network open"},
  "reglages.appareils.max_atteint": {"fr": "Cinq appareils au plus : révoquez-en un d’abord", "en": "Five devices at most: revoke one first"},
  "reglages.appareils.pc_seul": {"fr": "ce PC seulement", "en": "this PC only"},
  "reglages.appareils.perdu": {"fr": "Appareil perdu ? Révoquer ne suffit pas : vos clés ont voyagé dans l’archive. Régénérez-les chez chaque fournisseur :", "en": "Lost a device? Revoking is not enough: your keys travelled in the archive. Regenerate them with each provider:"},
  "reglages.appareils.qr_alt": {"fr": "QR d’appairage", "en": "Pairing QR code"},
  "reglages.appareils.revocation_refusee": {"fr": "Révocation refusée (HTTP {statut})", "en": "Revocation refused (HTTP {statut})"},
  "reglages.appareils.revoque": {"fr": "révoqué", "en": "revoked"},
  "reglages.appareils.revoque_toast": {"fr": "« {nom} » révoqué", "en": "“{nom}” revoked"},
  "reglages.appareils.revoquer": {"fr": "Révoquer", "en": "Revoke"},
  "reglages.appareils.revoquer_aide": {"fr": "Retire à « {nom} » tout accès, tout de suite (confirmation demandée)", "en": "Removes all access from “{nom}”, right away (asks for confirmation)"},
  "reglages.appareils.revoquer_confirm": {"fr": "Révoquer « {nom} » ? Il ne pourra plus rien lire sur ce PC, tout de suite. S’il est perdu, régénérez aussi vos clés chez chaque fournisseur (liens ci-dessous) : elles ont voyagé dans l’archive chiffrée.", "en": "Revoke “{nom}”? It will no longer be able to read anything on this PC, starting now. If it is lost, also regenerate your keys with each provider (links below): they travelled in the encrypted archive."},
  "reglages.appareils.revoquer_titre": {"fr": "Révoquer un appareil", "en": "Revoke a device"},
  "reglages.appareils.scanner": {"fr": "Scannez avec l’application Deepotus du téléphone. Valable {mm}:{ss}, un seul appareil.", "en": "Scan with the Deepotus app on your phone. Valid for {mm}:{ss}, one device only."},
  "reglages.appareils.titre": {"fr": "Appareils", "en": "Devices"},
  "reglages.apparence.aide": {"fr": "Animations et effets. Enregistré dans votre navigateur, appliqué tout de suite à tous les écrans.", "en": "Motion + flair toggles. Saved in your browser; apply across all screens immediately."},
